import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router } from '@angular/router';
import { ContactoService, Contacto } from '../contacto.service';

@Component({
  selector: 'app-contacto-list',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './contacto-list.component.html',
  styleUrls: ['./contacto-list.component.css'],
})
export class ContactoListComponent implements OnInit {
  contactos: Contacto[] = [];
  loading = true;
  error = '';

  constructor(
    private contactoService: ContactoService,
    private router: Router,
  ) {}

  ngOnInit() {
    this.cargarContactos();
  }

  cargarContactos() {
    this.loading = true;
    this.error = '';
    this.contactoService.listar().subscribe({
      next: (data) => {
        this.contactos = data;
        this.loading = false;
      },
      error: (err) => {
        this.error = 'Error al cargar contactos';
        this.loading = false;
      },
    });
  }

  crear() {
    this.router.navigate(['/contactos/nuevo']);
  }

  editar(id: number) {
    this.router.navigate(['/contactos', id, 'editar']);
  }

  eliminar(id: number) {
    if (confirm('¿Deseas eliminar este contacto?')) {
      this.contactoService.eliminar(id).subscribe({
        next: () => this.cargarContactos(),
        error: () => (this.error = 'Error al eliminar contacto'),
      });
    }
  }

  ver(id: number) {
    this.router.navigate(['/contactos', id]);
  }
}
<div class="container">
  <div class="header">
    <h2>Contactos</h2>
    <button class="btn btn-primary" (click)="crear()">+ Nuevo Contacto</button>
  </div>

  <div *ngIf="error" class="alert alert-danger">{{ error }}</div>
  <div *ngIf="loading" class="loading">Cargando contactos...</div>

  <div *ngIf="!loading && contactos.length > 0" class="cards-grid">
    <div *ngFor="let contacto of contactos" class="card">
      <div class="card-header">
        <h3>{{ contacto.nombre_contacto }}</h3>
        <span class="card-badge">{{ contacto.puesto_contacto }}</span>
      </div>
      <div class="card-body">
        <div class="card-row">
          <span class="label">Teléfono:</span>
          <span class="value">{{ contacto.telefono || 'N/A' }}</span>
        </div>
        <div class="card-row">
          <span class="label">Celular:</span>
          <span class="value">{{ contacto.celular || 'N/A' }}</span>
        </div>
        <div class="card-row">
          <span class="label">Correo:</span>
          <span class="value email-value">{{ contacto.correo_electronico }}</span>
        </div>
      </div>
      <div class="card-actions">
        <button class="btn btn-sm btn-info" (click)="ver(contacto.id_contacto!)">Ver</button>
        <button class="btn btn-sm btn-warning" (click)="editar(contacto.id_contacto!)">Editar</button>
        <button class="btn btn-sm btn-danger" (click)="eliminar(contacto.id_contacto!)">Eliminar</button>
      </div>
    </div>
  </div>

  <div *ngIf="!loading && contactos.length === 0" class="empty-state">
    <p>No hay contactos. <a (click)="crear()">Crear uno nuevo</a></p>
  </div>
</div>
